procedure PhysioCancelSession {
  about "Cancel a session and notify the patient"
  policy PhysioPolicy
  sheet Cancellations "Cancellations" { session_id: Text, patient: Text, mobile: Phone, event_id: Text }
  calendar Rooms "Rooms"
  trigger when new row r in Cancellations

  let ev = book Rooms { title: "cancelled", at: r.event_id, length: 0 minutes }
  cancel Rooms event r.event_id
  let m = draft sms to r.mobile: "Hi {r.patient default 'there'}, your session with the office has been cancelled."
  let ok = request approval of m from owner timeout 6 hours else stop "confirmation not approved"
  send ok
  notify owner "Cancelled session for {r.session_id}"
}

