  about "Assign a walker to a scheduled dog"
  policy DogPolicy
  sheet Walks "Walks" { dog: Text, owner: Text, phone: Phone, walk_at: DateTime, walker: Text, walker_phone: Phone, paid: Bool, status: Text, gate_code: Text private }
  trigger every day at 17:00

  let all = fetch Walks
  let recent = filter all where status == "scheduled" and days_between(walk_at, today()) <= 2 and walker == ""
  for each r in recent up to 40 {
    notify owner "{r.dog} ({r.walk_at}): assign the walker."
  }
}

