procedure NailsWinBack {
  about "Nudge clients whose service was long ago"
  policy NailsPolicy
  sheet Clients "Clients" { name: Text, phone: Phone, last_visit: Date, visits: Number, status: Text }
  trigger every thursday at 15:00

  let all = fetch Clients
  let old = filter all where days_between(last_visit, today()) >= 45 and status != "do-not-contact"
  let oldest = sort old by last_visit first 20
  for each r in oldest up to 20 {
    let m = draft sms to r.phone: "Hi {r.name default 'there'}, it's been a while! We'd love to see you again at the salon."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
  }
}
