procedure NailsRebookOffer {
  about "Nudge clients marked no-show"
  policy NailsPolicy
  sheet Appointments "Appointments" { client: Text, phone: Phone, start: DateTime, service: Text, price: Money, status: Text, allergy_notes: Text private }
  trigger every day at 19:00

  let all = fetch Appointments
  let recent = filter all where status == "no-show" and days_between(start, today()) <= 1 and days_between(start, today()) >= 0
  let n = summarize count of recent
  if n == 0 {
    stop "no no-show clients"
  }
  notify owner "No-show clients to rebook: {n}"
  for each r in recent up to 20 {
    let m = draft sms to r.phone: "Hi {r.client default 'there'}, our apologies! Reply to set up a new time."
    let ok = request approval of m from owner timeout 6 hours else skip
    send ok
    update r set status = "rebook-sent"
  }
}
