procedure IceRefunds {
  about "Handle refund requests within limits"
  policy IcePolicy
  sheet PartyCancellations "PartyCancellations" { ref: Text, host: Text, phone: Phone, deposit: Money, party_on: Date }
  trigger when new row r in PartyCancellations

  if days_between(r.party_on, today()) < 3 {
    notify owner "Short-notice refund for {r.ref} ({r.deposit}). Please handle it."
    stop "short notice goes to owner"
  }
  if r.deposit > $100.00 {
    notify owner "Large refund for {r.ref} ({r.deposit}). Please review."
    stop "large refund goes to owner"
  }
  if r.deposit <= $40.00 {
    refund r.deposit for r.ref reason "refund request"
  } else {
    refund r.deposit for r.ref reason "refund request", ask owner first timeout 1 day else stop "refund not approved"
  }
  let m = draft sms to r.phone: "Hi {r.host default 'there'}, your deposit of {r.deposit} has been refunded."
  let ok = request approval of m from owner timeout 1 day else stop "message not approved"
  send ok
}
